function mostrarMensagem(){var t=["Olá, Grunt!","Build automático ativado!","Menos trabalho manual, mais café ☕","Minificando ideias... 💡","Code like a ninja 🥷"],t=t[Math.floor(Math.random()*t.length)];let a=document.createElement("h2");a.textContent=t,a.style.color="#fff",a.style.textShadow="2px 2px 4px #000",a.style.opacity=0,a.style.transition="opacity 2s ease",document.body.appendChild(a),setTimeout(()=>{a.style.opacity=1},100)}mostrarMensagem();